# PTX kernel for fp16 matrix multiplication (C = A @ B) on RTX PRO 6000 (sm_120a)
PTX_SOURCE = r"""
.version 8.7
.target sm_120a
.address_size 64

.visible .entry matmul_fp16(
    .param .u64 matmul_fp16_param_0,   // A pointer (fp16)
    .param .u64 matmul_fp16_param_1,   // B pointer (fp16)
    .param .u64 matmul_fp16_param_2,   // C pointer (fp16)
    .param .u32 matmul_fp16_param_3    // N (matrix dimension)
)
{
    //--- registers -------------------------------------------------
    .reg .pred  %p<4>;
    .reg .b32   %r<10>;
    .reg .b64   %rd<13>;
    .reg .f16   %h<3>;
    .reg .f32   %f<4>;

    //--- load kernel parameters ------------------------------------
    ld.param.u64    %rd1, [matmul_fp16_param_0];   // A
    ld.param.u64    %rd2, [matmul_fp16_param_1];   // B
    ld.param.u64    %rd3, [matmul_fp16_param_2];   // C
    ld.param.u32    %r9,  [matmul_fp16_param_3];   // N

    //--- convert generic pointers to global address space ----------
    cvta.to.global.u64 %rd4, %rd1;   // A_global
    cvta.to.global.u64 %rd5, %rd2;   // B_global
    cvta.to.global.u64 %rd6, %rd3;   // C_global

    //--- compute row and column indices ---------------------------
    // row = blockIdx.y * blockDim.y + threadIdx.y
    mad.lo.s32 %r0, %ctaid.y, %ntid.y, %tid.y;
    // col = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32 %r1, %ctaid.x, %ntid.x, %tid.x;

    //--- bounds check --------------------------------------------
    setp.ge.s32 %p0, %r0, %r9;
    @%p0 bra $L_EXIT;
    setp.ge.s32 %p1, %r1, %r9;
    @%p1 bra $L_EXIT;

    //--- pre‑compute row * N --------------------------------------
    mul.lo.s32 %r2, %r0, %r9;          // r2 = row * N

    //--- accumulator (fp32) --------------------------------------
    mov.f32 %f3, 0.0;                  // sum = 0.0f

    //--- loop over k --------------------------------------------
    mov.u32 %r3, 0;                    // k = 0

$L_LOOP:
    setp.ge.s32 %p2, %r3, %r9;         // if k >= N exit loop
    @%p2 bra $L_AFTER_LOOP;

    //--- load A[row, k] (fp16) ---------------------------------
    add.s32 %r4, %r2, %r3;             // row*N + k
    mul.wide.s32 %rd7, %r4, 2;         // byte offset (2 bytes per half)
    add.s64 %rd8, %rd4, %rd7;          // address of A[row,k]
    ld.global.f16 %h0, [%rd8];

    //--- load B[k, col] (fp16) ---------------------------------
    mul.lo.s32 %r5, %r3, %r9;          // k * N
    add.s32 %r5, %r5, %r1;             // k*N + col
    mul.wide.s32 %rd9, %r5, 2;         // byte offset
    add.s64 %rd10, %rd5, %rd9;         // address of B[k,col]
    ld.global.f16 %h1, [%rd10];

    //--- convert to fp32 and fused multiply‑add -----------------
    cvt.f32.f16 %f0, %h0;
    cvt.f32.f16 %f1, %h1;
    fma.rn.f32 %f3, %f0, %f1, %f3;    // sum += a*b

    //--- increment k ---------------------------------------------
    add.u32 %r3, %r3, 1;
    bra $L_LOOP;

$L_AFTER_LOOP:
    //--- write result C[row, col] --------------------------------
    add.s32 %r6, %r2, %r1;             // row*N + col
    mul.wide.s32 %rd11, %r6, 2;        // byte offset
    add.s64 %rd12, %rd6, %rd11;        // address of C[row,col]

    cvt.rn.f16.f32 %h2, %f3;           // round to fp16
    st.global.f16 [%rd12], %h2;

$L_EXIT:
    ret;
}
"""

class ModelNew(nn.Module):
    """
    fp16 matrix multiplication (C = A @ B) using a hand‑written PTX kernel.
    All inputs must be square, half‑precision, and reside on the same CUDA device.
    """
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "inputs must be CUDA tensors"
        assert A.dtype == torch.float16 and B.dtype == torch.float16, "fp16 required"
        N = A.shape[0]
        assert A.shape == (N, N) and B.shape == (N, N), "inputs must be square matrices"

        C = torch.empty_like(A)

        BLOCK = 16  # 16×16 thread block
        grid_x = (N + BLOCK - 1) // BLOCK
        grid_y = (N + BLOCK - 1) // BLOCK

        ptx_launch(
            self.module,
            "matmul_fp16",
            (grid_x, grid_y, 1),          # grid dimensions
            (BLOCK, BLOCK, 1),            # block dimensions
            [A.data_ptr(), B.data_ptr(), C.data_ptr(), N]
        )
        return C
